// This file was generated by Slater.app - cards apparition.js


gsap.registerPlugin(ScrollTrigger);

// On définit la liste des sélecteurs à animer
const selectors = [
  '.services_card',
  '.chiffre-cle_block_bloc',
  '.case-studies_block',
  '.temoignages_block',
  '.blog34_item-link',
  '.groupe_grid_block',
  '.confiance_logo_block',
  '.faq6_question',
  '.processus_layout_card'
];

// On crée l'animation pour chaque type d'élément
selectors.forEach(selector => {

  // Batch permet d'animer les éléments par groupe dès qu'ils entrent à l'écran
  ScrollTrigger.batch(selector, {
    onEnter: batch => gsap.to(batch, {
      opacity: 1,
      y: 0,
      duration: 1,
      stagger: 0.15,
      ease: "power3.out",
      overwrite: true
    }),
    start: "top 85%",
    once: true // L'animation ne se joue qu'une fois pour les perfs
  });

});


